#!/usr/bin/env node
'use strict';
// AI: below section was generated by an AI
/*
 * Virtual WLED device: http + websocket server (contract: VDEV.md). Node 18+, no npm packages.
 *
 *   node server.js [--port 8091] [--host 127.0.0.1] [--fxsim <dir|file>] [--repo <WLED-main dir>]
 *
 * Routes: GET /__info (this server), then home_api.handle (usermod /home/*), then core_api.handle (WLED core API + UI),
 * then 404. Upgrades: /home/ws -> home_api.upgrade, /ws -> core_api.upgrade, anything else -> 404.
 * core_api.js / home_api.js are optional: while one is missing (or fails to load) the server keeps serving the rest,
 * logs a warning and retries loading it (at most every 2 s) so a module written later is picked up without a restart.
 */

const http = require('http');
const fs = require('fs');
const path = require('path');
const { refuseUpgrade } = require('./wslib.js');

function argVal(name, dflt) {
  const i = process.argv.indexOf(name);
  return (i > 0 && i + 1 < process.argv.length) ? process.argv[i + 1] : dflt;
}
if (process.argv.includes('-h') || process.argv.includes('--help')) {
  console.log('usage: node server.js [--port 8091] [--host 127.0.0.1] [--fxsim <dir|file>] [--repo <WLED-main dir>]');
  process.exit(0);
}
const PORT = Math.max(1, Math.min(65535, parseInt(argVal('--port', '8091'), 10) || 8091));
const HOST = argVal('--host', '127.0.0.1');

const dev = require('./device.js');

/* ------------------------------------------------------------------ optional modules with retry */

function optionalModule(file) {
  const full = path.join(__dirname, file);
  const m = { file, mod: null, lastTry: 0, lastErr: '', mtime: 0 };
  m.get = () => {
    if (m.mod) return m.mod;
    const now = Date.now();
    if (now - m.lastTry < 2000) return null;
    m.lastTry = now;
    let st;
    try { st = fs.statSync(full); } catch (_) {
      if (m.lastErr !== 'missing') { console.warn(`[server] ${file} not found - its routes answer 404 until it exists`); m.lastErr = 'missing'; }
      return null;
    }
    if (st.mtimeMs === m.mtime && m.lastErr) return null;  // same broken file: don't retry until it changes
    m.mtime = st.mtimeMs;
    try {
      delete require.cache[require.resolve(full)];
      const mod = require(full);
      if (!mod || typeof mod.handle !== 'function') throw new Error('does not export handle(req, res, dev)');
      m.mod = mod;
      m.lastErr = '';
      console.log(`[server] ${file} loaded`);
      return mod;
    } catch (e) {
      m.lastErr = e.message;
      console.warn(`[server] ${file} failed to load: ${e && e.stack || e}`);
      return null;
    }
  };
  return m;
}
const HOME = optionalModule('home_api.js');
const CORE = optionalModule('core_api.js');

/* ------------------------------------------------------------------ /__info */

function serverInfo() {
  const o = { virtual: true, mirrors: 'RC4b', cpp_md5: null, page_served: null };
  const home = HOME.get();
  if (home && typeof home.homeInfo === 'function') {
    try { Object.assign(o, home.homeInfo()); } catch (e) { o.homeInfoError = e.message; }
  }
  Object.assign(o, {
    virtual: true,
    fxsim: dev.fxsimInfo(),
    port: PORT,
    modules: { home_api: !!HOME.mod, core_api: !!CORE.mod },
    build: dev.build,
    effects: dev.effects.length,
    palettes: dev.palettes.length,
  });
  return o;
}

/* ------------------------------------------------------------------ http */

async function callHandle(m, req, res) {
  const mod = m.get();
  if (!mod) return false;
  let r = mod.handle(req, res, dev);
  if (r && typeof r.then === 'function') r = await r;
  return !!r;
}

const server = http.createServer(async (req, res) => {
  try {
    const pathname = (req.url || '/').split('?')[0];
    if (pathname === '/__info' && (req.method === 'GET' || req.method === 'HEAD')) {
      const body = JSON.stringify(serverInfo(), null, 1);
      res.writeHead(200, { 'Content-Type': 'application/json', 'Cache-Control': 'no-store', 'Content-Length': Buffer.byteLength(body) });
      res.end(req.method === 'HEAD' ? undefined : body);
      return;
    }
    if (await callHandle(HOME, req, res)) return;
    if (await callHandle(CORE, req, res)) return;
    if (!res.headersSent) {
      res.writeHead(404, { 'Content-Type': 'text/plain', 'Cache-Control': 'no-store' });
      res.end('Not Found');
    }
  } catch (e) {
    console.error('[server] ' + req.method + ' ' + req.url + ' failed: ' + (e && e.stack || e));
    if (!res.headersSent) { res.writeHead(500, { 'Content-Type': 'text/plain' }); res.end('Internal Server Error'); }
    else res.destroy();
  }
});

/* ------------------------------------------------------------------ websocket upgrades */

server.on('upgrade', (req, socket) => {
  socket.on('error', () => {});
  const pathname = (req.url || '/').split('?')[0];
  const m = pathname === '/home/ws' ? HOME : pathname === '/ws' ? CORE : null;
  let ok = false;
  try {
    const mod = m ? m.get() : null;
    if (mod && typeof mod.upgrade === 'function') ok = !!mod.upgrade(req, socket, dev);
  } catch (e) {
    console.error('[server] upgrade ' + req.url + ' failed: ' + (e && e.stack || e));
  }
  if (!ok && !socket.destroyed && socket.writable) refuseUpgrade(socket, 404);  // false = "not mine"
});

server.on('clientError', (err, socket) => { if (socket.writable) socket.end('HTTP/1.1 400 Bad Request\r\n\r\n'); });

server.on('error', (e) => {
  console.error('[server] ' + (e.code === 'EADDRINUSE' ? `port ${PORT} is already in use (try --port <n>)` : e.message));
  process.exit(1);
});

server.listen(PORT, HOST, () => {
  HOME.get(); CORE.get();  // load (or warn about) both modules now
  const shown = (HOST === '0.0.0.0' || HOST === '::') ? '127.0.0.1' : HOST;
  const fx = dev.fxsimInfo();
  console.log(`Virtual WLED device (${dev.build.env}): ${dev.effects.length} effect slots (${fx.total} real), ${dev.palettes.length} palettes, ${dev.LEDS} LEDs`);
  console.log(`  fxsim: ${fx.dir || 'none'} - ${fx.implemented}/${fx.total} effects run, ${fx.fallback.length} fall back`);
  console.log(`  WLED UI:      http://${shown}:${PORT}/`);
  console.log(`  Home Gadgets: http://${shown}:${PORT}/home`);
  if (HOST === '127.0.0.1') console.log('  (local only; use --host 0.0.0.0 to reach it from a phone on the same network)');
});

function shutdown() { dev.stop(); server.close(); process.exit(0); }
process.on('SIGINT', shutdown);
process.on('SIGTERM', shutdown);
// AI: end
